import { useId, useState, type FormEvent } from 'react';
import { Alert, Button, Select, Stack, Switch, TextField } from '@jinx-ui/react';

const ROLES = [
  { value: 'viewer', label: 'Наблюдатель' },
  { value: 'editor', label: 'Редактор' },
  { value: 'admin', label: 'Администратор' },
];

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

export default function TeamInviteForm() {
  const formId = useId();
  const [email, setEmail] = useState('');
  const [touched, setTouched] = useState(false);
  const [role, setRole] = useState('viewer');
  const [notify, setNotify] = useState(true);
  const [invitedEmail, setInvitedEmail] = useState<string | null>(null);

  const isEmailValid = EMAIL_PATTERN.test(email.trim());
  const showError = touched && !isEmailValid;

  function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (!isEmailValid) return;
    setInvitedEmail(email.trim());
    setEmail('');
    setTouched(false);
  }

  return (
    <Stack direction="column" gap="md" style={{ maxWidth: 'var(--jx-size-container-sm)' }}>
      {invitedEmail && (
        <Alert
          status="success"
          title="Приглашение отправлено"
          closable
          onClose={() => setInvitedEmail(null)}
        >
          {invitedEmail} получит доступ с ролью «
          {ROLES.find((r) => r.value === role)?.label}».
        </Alert>
      )}

      <form id={formId} onSubmit={handleSubmit} noValidate>
        <Stack direction="column" gap="md">
          <TextField
            label="Рабочая почта"
            type="email"
            name="email"
            autoComplete="email"
            placeholder="name@company.com"
            value={email}
            onChange={(value: string) => setEmail(value)}
            onBlur={() => setTouched(true)}
            invalid={showError}
            helperText={
              showError
                ? 'Введите адрес в формате name@company.com'
                : 'Приглашение действует 7 дней.'
            }
            required
          />

          <Select
            label="Роль в команде"
            name="role"
            value={role}
            onChange={(value: string) => setRole(value)}
            options={ROLES}
          />

          <Switch
            label="Отправить уведомление по почте"
            checked={notify}
            onChange={(checked: boolean) => setNotify(checked)}
          />

          <Button type="submit" variant="primary" disabled={!isEmailValid}>
            Пригласить
          </Button>
        </Stack>
      </form>
    </Stack>
  );
}

